    private UserRepository $userRepository;","","    private HistoryRepository $historyRepository;","","    private FavoriteRepository $favoriteRepository;","","    private FoodService $foodService;","","    private ?array $currentUser = null;","","    public function __construct($app)","    {","        parent::__construct($app);","","        if (!$this-\u003esession-\u003eisLoggedIn()) {","            $this-\u003eredirect('/login');","            exit;","        }","","        $this-\u003euserRepository = new UserRepository($this-\u003edb);","        $this-\u003ehistoryRepository = new HistoryRepository($this-\u003edb);","        $this-\u003efavoriteRepository = new FavoriteRepository($this-\u003edb);","        $this-\u003efoodService = new FoodService(new FoodRepository($this-\u003edb));","    }","","    public function index(): void","    {","        $user = $this-\u003ecurrentUser();","        $stats = $this-\u003eactivityStats((int) $user['id']);","","        $this-\u003erenderDashboard('dashboard/index', [","            'title' =\u003e 'Dashboard · Taste of Macau',","            'activePage' =\u003e 'overview',","            'user' =\u003e $user,","            'stats' =\u003e $stats,","            'recentSearches' =\u003e $this-\u003eformatSearchEntries($this-\u003ehistoryRepository-\u003egetSearchHistory((int) $user['id'], 5)),","            'recentBrowses' =\u003e $this-\u003eformatBrowseEntries($this-\u003ehistoryRepository-\u003egetBrowseHistory((int) $user['id'], 5)),","        ]);","    }","","    public function profile(): void","    {","        $this-\u003erenderDashboard('dashboard/profile', [","            'title' =\u003e 'Profile · Taste of Macau',","            'activePage' =\u003e 'profile',","            'user' =\u003e $this-\u003ecurrentUser(),","        ]);","    }","","    public function updateProfile(): void","    {","        if (!$this-\u003evalidateCsrf('/dashboard/profile')) {","            return;","        }","","        $user = $this-\u003ecurrentUser();","        $data = [","            'username' =\u003e trim((string) $this-\u003erequest-\u003epost('username', '')),","            'email' =\u003e strtolower(trim((string) $this-\u003erequest-\u003epost('email', ''))),","            'locale' =\u003e trim((string) $this-\u003erequest-\u003epost('locale', 'zh')),","        ];","","        $validation = $this-\u003eapp-\u003evalidator()-\u003evalidate($data, [","            'username' =\u003e 'required|min:3|max:50',","            'email' =\u003e 'required|email',","        ]);","","        $errors = $validation['errors'];","","        if (!in_array($data['locale'], ['zh', 'en', 'pt'], true)) {","            $errors['locale'][] = 'Please select a valid locale.';","        }","","        if ($data['email'] !== strtolower((string) ($user['email'] ?? ''))) {","            $existing = $this-\u003euserRepository-\u003efindByEmail($data['email']);","","            if (is_array($existing) \u0026\u0026 (int) ($existing['id'] ?? 0) !== (int) $user['id']) {","                $errors['email'][] = 'The email field has already been taken.';","            }","        }","","        if ($errors !== []) {","            $this-\u003eflashFormState($errors, $data);","            $this-\u003eredirect('/dashboard/profile');","            return;","        }","","        $changes = [];","","        foreach (['username', 'email', 'locale'] as $field) {","            if (($user[$field] ?? null) !== $data[$field]) {","                $changes[$field] = $data[$field];","            }","        }","","        if ($changes === []) {","            $this-\u003esession-\u003eset('username', $data['username']);","            $this-\u003esession-\u003eset('locale', $data['locale']);","            $this-\u003esession-\u003eflash('success', 'Your profile is already up to date.');","            $this-\u003eredirect('/dashboard/profile');","            return;","        }","","        $updated = $this-\u003euserRepository-\u003eupdate((int) $user['id'], $changes);","","        if (!$updated) {","            $this-\u003esession-\u003eflash('error', 'Unable to update your profile right now. Please try again.');","            $this-\u003esession-\u003eflash('old', $data);","            $this-\u003eredirect('/dashboard/profile');","            return;","        }","","        $this-\u003ecurrentUser = array_merge($user, $changes);","        $this-\u003esession-\u003eset('username', $this-\u003ecurrentUser['username'] ?? $data['username']);","        $this-\u003esession-\u003eset('locale', $this-\u003ecurrentUser['locale'] ?? $data['locale']);","        $this-\u003esession-\u003eflash('success', 'Your profile has been updated successfully.');","        $this-\u003eredirect('/dashboard/profile');","    }","","    public function searchHistory(): void","    {","        $user = $this-\u003ecurrentUser();","        $page = $this-\u003eresolvePage();","        $history = $this-\u003epaginatedSearchHistory((int) $user['id'], $page, 10);","","        $this-\u003erenderDashboard('dashboard/search-history', [","            'title' =\u003e 'Search History · Taste of Macau',","            'activePage' =\u003e 'search-history',","            'user' =\u003e $user,","            'entries' =\u003e $this-\u003eformatSearchEntries($history['items']),","            'pagination' =\u003e $history['pagination'],","        ]);","    }","","    public function browseHistory(): void","    {","        $user = $this-\u003ecurrentUser();","        $page = $this-\u003eresolvePage();","        $history = $this-\u003epaginatedBrowseHistory((int) $user['id'], $page, 9);","","        $this-\u003erenderDashboard('dashboard/browse-history', [","            'title' =\u003e 'Browse History · Taste of Macau',","            'activePage' =\u003e 'browse-history',","            'user' =\u003e $user,","            'entries' =\u003e $this-\u003eformatBrowseEntries($history['items']),","            'pagination' =\u003e $history['pagination'],","        ]);","    }","","    public function favorites(): void","    {","        $user = $this-\u003ecurrentUser();","        $locale = (string) ($user['locale'] ?? $this-\u003eresolveLocale());","        $favorites = array_map(function (array $entry) use ($locale): array {","            $food = $this-\u003efoodService-\u003eformatFood($entry, $locale);","            $food['is_favorited'] = true;","            $food['favorited_at'] = (string) ($entry['favorited_at'] ?? '');","","            return $food;","        }, $this-\u003efavoriteRepository-\u003egetUserFavorites((int) $user['id']));","","        $this-\u003erenderDashboard('dashboard/favorites', [","            'title' =\u003e 'Favorites · Taste of Macau',","            'activePage' =\u003e 'favorites',","            'user' =\u003e $user,","            'favorites' =\u003e $favorites,","        ]);","    }","","    public function clearSearchHistory(): void","    {","        if (!$this-\u003evalidateCsrf('/dashboard/search-history')) {","            return;","        }","","        $deleted = $this-\u003ehistoryRepository-\u003eclearSearchHistory((int) $this-\u003ecurrentUser()['id']);","        $this-\u003esession-\u003eflash('success', $deleted \u003e 0 ? 'Search history cleared.' : 'Search history was already empty.');","        $this-\u003eredirect('/dashboard/search-history');","    }","","    public function clearBrowseHistory(): void","    {","        if (!$this-\u003evalidateCsrf('/dashboard/browse-history')) {","            return;","        }","","        $deleted = $this-\u003ehistoryRepository-\u003eclearBrowseHistory((int) $this-\u003ecurrentUser()['id']);","        $this-\u003esession-\u003eflash('success', $deleted \u003e 0 ? 'Browse history cleared.' : 'Browse history was already empty.');","        $this-\u003eredirect('/dashboard/browse-history');","    }","","    private function renderDashboard(string $template, array $data = []): void","    {","        $user = $data['user'] ?? $this-\u003ecurrentUser();","        $locale = (string) ($user['locale'] ?? $this-\u003eresolveLocale());","","        $this-\u003eview($template, array_merge([","            'app' =\u003e $this-\u003eapp,","            'user' =\u003e $user,","            'locale' =\u003e $locale,","            'csrfToken' =\u003e $this-\u003ecsrf-\u003egetToken(),","            'extraScripts' =\u003e '\u003cscript src=\"/assets/js/dashboard.js\"\u003e\u003c/script\u003e',","        ], $data));","    }","","    private function currentUser(): array","    {","        if ($this-\u003ecurrentUser !== null) {","            return $this-\u003ecurrentUser;","        }","","        $user = $this-\u003euserRepository-\u003efindById((int) $this-\u003esession-\u003euserId());","","        if (!is_array($user)) {","            $this-\u003esession-\u003edestroy();","            $this-\u003esession-\u003estart();","            $this-\u003esession-\u003eflash('error', 'Please log in again to continue.');","            $this-\u003eredirect('/login');","            exit;","        }","","        $user['locale'] = in_array((string) ($user['locale'] ?? 'zh'), ['zh', 'en', 'pt'], true)","            ? (string) $user['locale']","            : 'zh';","","        $this-\u003ecurrentUser = $user;","","        return $this-\u003ecurrentUser;","    }","","    private function activityStats(int $userId): array","    {","        $searches = $this-\u003edb-\u003efetch('SELECT COUNT(*) AS aggregate FROM search_history WHERE user_id = :user_id', [':user_id' =\u003e $userId]);","","        return [","            'total_searches' =\u003e (int) ($searches['aggregate'] ?? 0),","            'total_browses' =\u003e $this-\u003ehistoryRepository-\u003ecountBrowseHistory($userId),","            'total_favorites' =\u003e $this-\u003efavoriteRepository-\u003ecount($userId),","            'member_since' =\u003e (string) ($this-\u003ecurrentUser()['created_at'] ?? ''),","        ];","    }","","    private function paginatedSearchHistory(int $userId, int $page, int $perPage): array","    {","        $pdo = $this-\u003edb-\u003epdo();","        $totalStatement = $pdo-\u003eprepare('SELECT COUNT(*) FROM search_history WHERE user_id = :user_id');","        $totalStatement-\u003ebindValue(':user_id', $userId, PDO::PARAM_INT);","        $totalStatement-\u003eexecute();","        $total = (int) $totalStatement-\u003efetchColumn();","","        $totalPages = max(1, (int) ceil($total / $perPage));","        $currentPage = min($page, $totalPages);","        $offset = max(0, ($currentPage - 1) * $perPage);","","        $statement = $pdo-\u003eprepare(","            'SELECT id, query, filters_json, results_count, created_at","             FROM search_history","             WHERE user_id = :user_id","             ORDER BY created_at DESC, id DESC","             LIMIT :limit OFFSET :offset'","        );","        $statement-\u003ebindValue(':user_id', $userId, PDO::PARAM_INT);","        $statement-\u003ebindValue(':limit', $perPage, PDO::PARAM_INT);","        $statement-\u003ebindValue(':offset', $offset, PDO::PARAM_INT);","        $statement-\u003eexecute();","","        return [","            'items' =\u003e $statement-\u003efetchAll(),","            'pagination' =\u003e $this-\u003epagination($currentPage, $perPage, $total, '/dashboard/search-history'),","        ];","    }","","    private function paginatedBrowseHistory(int $userId, int $page, int $perPage): array","    {","        $total = $this-\u003ehistoryRepository-\u003ecountBrowseHistory($userId);","","        $totalPages = max(1, (int) ceil($total / $perPage));","        $currentPage = min($page, $totalPages);","        $offset = max(0, ($currentPage - 1) * $perPage);","","        return [","            'items' =\u003e $this-\u003ehistoryRepository-\u003egetPaginatedBrowseHistory($userId, $perPage, $offset),","            'pagination' =\u003e $this-\u003epagination($currentPage, $perPage, $total, '/dashboard/browse-history'),","        ];","    }","","    private function formatSearchEntries(array $entries): array","    {","        return array_map(static function (array $entry): array {","            $filters = self::decodeFilters($entry['filters_json'] ?? null);","            $params = ['q' =\u003e (string) ($entry['query'] ?? '')];","","            if (isset($filters['category']) \u0026\u0026 is_string($filters['category']) \u0026\u0026 trim($filters['category']) !== '') {","                $params['category'] = trim($filters['category']);","            }","","            if (isset($filters['service']) \u0026\u0026 is_string($filters['service']) \u0026\u0026 trim($filters['service']) !== '') {","                $params['service'] = trim($filters['service']);","            }","","            return [","                'id' =\u003e (int) ($entry['id'] ?? 0),","                'query' =\u003e (string) ($entry['query'] ?? ''),","                'filters' =\u003e $filters,","                'results_count' =\u003e (int) ($entry['results_count'] ?? 0),","                'created_at' =\u003e (string) ($entry['created_at'] ?? ''),","                'rerun_url' =\u003e '/explore?' . http_build_query($params),","            ];","        }, $entries);","    }","","    private function formatBrowseEntries(array $entries): array","    {","        $locale = (string) ($this-\u003ecurrentUser()['locale'] ?? $this-\u003eresolveLocale());","","        return array_map(function (array $entry) use ($locale): array {","            if (($entry['item_type'] ?? 'food') === 'restaurant') {","                $restaurant = $this-\u003eformatBrowseRestaurant($entry, $locale);","","                return [","                    'id' =\u003e (int) ($entry['id'] ?? 0),","                    'type' =\u003e 'restaurant',","                    'created_at' =\u003e (string) ($entry['created_at'] ?? ''),","                    'item' =\u003e $restaurant,","                    'restaurant' =\u003e $restaurant,","                ];","            }","","            $food = $this-\u003efoodService-\u003eformatFood($entry, $locale);","","            return [","                'id' =\u003e (int) ($entry['id'] ?? 0),","                'type' =\u003e 'food',","                'created_at' =\u003e (string) ($entry['created_at'] ?? ''),","                'item' =\u003e $food,","                'food' =\u003e $food,","            ];","        }, $entries);","    }","","    private function formatBrowseRestaurant(array $entry, string $locale): array","    {","        $resolvedLocale = in_array($locale, ['en', 'zh', 'pt'], true) ? $locale : 'zh';","","        return [","            'id' =\u003e (int) ($entry['restaurant_id'] ?? 0),","            'name' =\u003e $this-\u003elocalizedValue($entry, 'name', $resolvedLocale),","            'description' =\u003e $this-\u003elocalizedValue($entry, 'description', $resolvedLocale),","            'image_url' =\u003e (string) ($entry['image_url'] ?? ''),","            'area' =\u003e $this-\u003elocalizedValue($entry, 'area', $resolvedLocale),","            'price_range' =\u003e (string) ($entry['price_range'] ?? ''),","            'rating' =\u003e isset($entry['avg_rating']) ? (float) $entry['avg_rating'] : (float) ($entry['rating'] ?? 0),","            'category_name' =\u003e $this-\u003eviewEngine-\u003et('restaurantDetail.restaurant', $resolvedLocale),","            'detail_url' =\u003e '/restaurant/' . (int) ($entry['restaurant_id'] ?? 0),","        ];","    }","","    private function localizedValue(array $row, string $prefix, string $locale): string","    {","        foreach ([$prefix . '_' . $locale, $prefix . '_zh', $prefix . '_en', $prefix . '_pt', $prefix] as $key) {","            if (array_key_exists($key, $row) \u0026\u0026 $row[$key] !== null \u0026\u0026 $row[$key] !== '') {","                return (string) $row[$key];","            }","        }","","        return '';","    }","","    private function pagination(int $page, int $perPage, int $total, string $